import * as React from "react";
import styles from "./LicenseMatrixView.module.scss";
import {
  LicenseAllocationService,
  ILicenseAllocation
} from "../../services/LicenseAllocationService";


interface IProps {

  serviceContext: any;

  onClientSelect?: (client: string) => void;

  onBack?: () => void;

}


interface IState {

  loading: boolean;

  allocations: ILicenseAllocation[];

  clients: string[];

  licenses: string[];

  error?: string;

}



export default class LicenseMatrixView
extends React.Component<IProps, IState> {


private service: LicenseAllocationService;



constructor(props:IProps){

super(props);

this.service =
new LicenseAllocationService(
props.serviceContext
);


this.state = {

loading:true,

allocations:[],

clients:[],

licenses:[]

};

}



public async componentDidMount(){

await this.loadData();

}



private async loadData(){

try{


const data =
await this.service.getAllocations();



const clients =
Array.from(

new Set(

data

.map(
x => x.ITRequest?.Client?.Title
)

.filter(Boolean)

)

) as string[];




const licenses =
Array.from(

new Set(

data

.map(
x => x.License?.Title
)

.filter(Boolean)

)

) as string[];




this.setState({

allocations:data,

clients,

licenses,

loading:false

});



}

catch(error){


console.error(
"License Load Error",
error
);


this.setState({

loading:false,

error:
"Unable to load license allocations"

});


}

}




private getCount(

client:string,

license:string

):number{


return this.state.allocations.filter(

item =>


item.ITRequest?.Client?.Title === client

&&

item.License?.Title === license

&&

(

typeof item.Status === "string"

?

item.Status

:

item.Status?.Value

)

!== "Released"


).length;


}





public render(){


if(this.state.loading){


return (

<div className={styles.loading}>

Loading licenses...

</div>

);


}



if(this.state.error){


return (

<div className={styles.error}>

{this.state.error}

</div>

);


}



return (

<div className={styles.page}>


<div className={styles.header}>


<div>

<h2>

License Allocation Matrix

</h2>

<p>

Client wise license usage

</p>

</div>



<button

className={styles.backButton}

onClick={
this.props.onBack
}

>

← Dashboard

</button>


</div>




<div className={styles.tableContainer}>


<table>


<thead>

<tr>


<th>

Client

</th>


{

this.state.licenses.map(

license =>

<th key={license}>

{license}

</th>

)

}


</tr>

</thead>




<tbody>


{

this.state.clients.map(

client =>


<tr

key={client}

className={styles.row}

onClick={

()=>this.props.onClientSelect?.(client)

}


>


<td

className={styles.clientName}

>

{client}

</td>



{

this.state.licenses.map(

license =>


<td

key={license}

className={styles.count}

>


{

this.getCount(

client,

license

)

}


</td>


)

}



</tr>


)

}



</tbody>



</table>


{

this.state.clients.length === 0 &&


<div className={styles.empty}>

No license allocations found

</div>


}



</div>



</div>

);


}



}